def calculate_task_metrics(task):
    task.U = task.C / task.T
    task.lambda = task.C / task.D

def compute_RTA_EDF_iteration(task_k, task_set, m):
    R_ub_k = task_k.C
    while True:
        interference_sum = 0
        for task_i in task_set:
            if task_i != task_k:
                workload_i = calculate_workload_bound_formal(task_i, R_ub_k)
                interference_edf_i_k = calculate_interference_edf(task_i, task_k, m)
                available_interference_time = R_ub_k - task_k.C + 1

                bounded_interference_i_k = min(workload_i, interference_edf_i_k, available_interference_time)
                interference_sum += bounded_interference_i_k

        new_R_ub_k = task_k.C + (1 / m) * interference_sum

        if abs(new_R_ub_k - R_ub_k) < 1e-9:
            break
        R_ub_k = new_R_ub_k

        if R_ub_k > some_large_bound:
            return float('inf')

    return R_ub_k

def compute_RTA_FP_iteration(task_k, task_set, m):
    # Assume task_set is sorted by priority, highest first.
    R_ub_k = task_k.C
    while True:
        interference_sum = 0
        for task_i in task_set:
            if task_i.priority > task_k.priority: # Higher priority task
                workload_i = calculate_workload_bound_formal(task_i, R_ub_k)
                available_interference_time = R_ub_k - task_k.C + 1

                bounded_interference_i_k = min(workload_i, available_interference_time)
                interference_sum += bounded_interference_i_k

        new_R_ub_k = task_k.C + (1 / m) * interference_sum

        if abs(new_R_ub_k - R_ub_k) < 1e-9:
            break
        R_ub_k = new_R_ub_k

        if R_ub_k > some_large_bound:
            return float('inf')

    return R_ub_k

def check_schedulability_edf(task_set, m):
    for task_k in task_set:
        R_ub_k = compute_RTA_EDF_iteration(task_k, task_set, m)
        if R_ub_k == float('inf') or R_ub_k > task_k.D:
            return False # Task k is not schedulable
    return True # All tasks are schedulable

def check_schedulability_fp(task_set, m):
    # Assume task_set is sorted by priority, highest first.
    for task_k in task_set:
        R_ub_k = compute_RTA_FP_iteration(task_k, task_set, m)
        if R_ub_k == float('inf') or R_ub_k > task_k.D:
            return False # Task k is not schedulable
    return True # All tasks are schedulable
